{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    edges = []
    for a, b, d in distances:
        w = max(core_dist[a], core_dist[b], d)
        if a > b:
            a, b = b, a
        edges.append((a, b, w))
    edges.sort(key=lambda x: (x[2], x[0], x[1]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph: cannot compute MST')
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
